    if(!v){ v = document.createElement('video'); v.autoplay = true; v.playsInline = true; v.muted = true; v.setAttribute('playsinline',''); v.dataset.lwKey = key; }
    const cur = v.srcObject && v.srcObject.getVideoTracks()[0];
