  const _lrnToolsHTML = filter => `<div class="ll-tools">${filter ? _lmFbtnHTML() : ''}${_lrnSearchHTML()}</div>`;
  // the Learn tab, below the top card (Justin, 2026-10-02, option C): a row of articles for each state that has
