    const done = new Set(Object.keys(ans).filter(x=>/^nj:/.test(x) && (ans[x] || [])[0]).map(x=>x.split(':')[2]));
    const d0 = new Date(), dayN = Math.floor((d0 - new Date(d0.getFullYear(), 0, 0)) / 864e5);
