    const daysOf = (list, q) => { const by = {}; list.forEach(it=>{ (by[it.day || ''] = by[it.day || ''] || []).push(it); }); return Object.keys(by).sort().reverse().map(k=>dayPage(k, by[k], q)).join(''); };
