      let first = Infinity;
      try{ (Store.checkins() || []).forEach(c=>{ const t = +new Date(c.t); if(t < first) first = t; }); }catch(e){}
      try{ (Store.sessions() || []).forEach(s=>{ const t = +new Date(s && s.t); if(t < first) first = t; }); }catch(e){}
