    return `<details class="rd-toc"><summary><span>In this article</span><span class="rd-toc-n">${toc.length} sections</span><span class="rd-toc-chev" aria-hidden="true">${CHEV}</span></summary><ol>${toc.map(li).join('')}</ol></details>`;
