    if(!raw){ try{ const a = JSON.parse(localStorage.getItem(UP_EMO_KEY) || 'null'); if(Array.isArray(a) && a.filter(_emoOk).length){ raw = a.filter(_emoOk); _emoSave(raw); } }catch(e){} }
